// chunkReader returns at most n bytes per Read call.
type chunkReader struct {
	b []byte
	n int
}

func (c *chunkReader) Read(p []byte) (int, error) {
	if len(c.b) == 0 {
		return 0, io.EOF
	}
	m := c.n
	if m > len(c.b) {
		m = len(c.b)
	}
	if m > len(p) {
		m = len(p)
	}
	copy(p, c.b[:m])
	c.b = c.b[m:]
	return m, nil
}

