func main() {
	// 1-byte reads over the text blob.
	r := bzip2.NewReader(bytes.NewReader(s_bz2_text))
	out := new(bytes.Buffer)
	one := make([]byte, 1)
	for {
		n, err := r.Read(one)
		if n > 0 {
			out.Write(one[:n])
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			fmt.Println("read1-err", err)
			break
		}
	}
	fmt.Println("read1-rt", bytes.Equal(out.Bytes(), s_raw_text))
	// 5-byte-chunk source.
	r2 := bzip2.NewReader(&chunkReader{b: bytes.Clone(s_bz2_text), n: 5})
	out2, err2 := io.ReadAll(r2)
	fmt.Println("chunk5-rt", bytes.Equal(out2, s_raw_text), err2 == nil)
	// concatenated members: the reader transparently continues into the
	// next member; output is the concatenation of both.
	cat := append(bytes.Clone(s_bz2_hello), s_bz2_zeros...)
	r3 := bzip2.NewReader(bytes.NewReader(cat))
	part1, _ := io.ReadAll(r3)
	want := append(bytes.Clone(s_raw_hello), s_raw_zeros...)
	fmt.Println("concat-rt", bytes.Equal(part1, want))
}
